element.execute_javascript.source:
def execute_javascript(
    self,
    code: str,
    argument: object | None = None,
    execution_world: str = "ISOLATED",
) -> Any:
    '''在当前元素上执行 JavaScript 脚本。

    Args:
        code: 要执行的 JS 脚本，必须为 JavaScript 函数字符串，如：

            ```python
            """
            function (element, args) {
                // element 表示当前 HTML 元素
                // args 表示输入的参数
                return args;
            }
            """
            ```

        argument: 要传入 JS 函数的参数，支持字符串、数字、布尔值、列表和字典。
            默认 None，函数收到 undefined；列表和字典无需先转为 JSON 字符串。
        execution_world: 运行环境，支持 "ISOLATED"（隔离环境）和 "MAIN"（网页环境），
            默认为 "ISOLATED"。

    Returns:
        Any：返回 JS 脚本执行结果；无返回值、undefined 和 null 返回 None。
    '''

    if execution_world not in {"ISOLATED", "MAIN"}:
        raise InvalidParamsError("execution_world 必须为 ISOLATED 或 MAIN")
    return self._raw.evaluate_js(str(code), argument=argument, execution_world=execution_world)
